from dataclasses import replace; from datetime import date; from decimal import Decimal; from unittest.mock import AsyncMock; import pytest; from sqlalchemy import func, select; from src.composition import compose_statement_posting_dependencies; from src.extraction.extension.statement_posting import try_auto_post_statement_opening_balance; from src.ledger import Account, AccountType, JournalEntry, JournalEntryStatus, calculate_account_balance, initialize_opening_positions, list_opening_positions, void_journal_entry; from src.reporting.extension.balance_sheet import generate_balance_sheet; from tests.factories import StatementSummaryFactory
@pytest.mark.parametrize('case', ['missing_fields', 'missing_provider', 'provider_failure', 'invalid_rate', 'valid_rate'])
async def test_statement_opening_requires_valid_historical_inputs(db, test_user, case):
    'AC-extraction.opening-lineage.1'; account = Account(user_id=test_user.id, name='Foreign source', type=AccountType.ASSET, currency='USD'); db.add(account); await db.flush(); statement = StatementSummaryFactory.build(user_id=test_user.id, account_id=account.id, currency='USD', opening_balance=Decimal('100'), period_start=date(2026, 1, 1))
    if case == 'missing_fields': statement.opening_balance = None
    provider = AsyncMock(side_effect=ValueError('FX unavailable')) if case == 'provider_failure' else AsyncMock(return_value=Decimal('0') if case == 'invalid_rate' else Decimal('1.35')); dependencies = replace(compose_statement_posting_dependencies(), fx_rate_provider=provider, fx_rate_error=ValueError)
    if case == 'valid_rate': assert await try_auto_post_statement_opening_balance(db, statement, test_user.id, dependencies=dependencies); provider.assert_awaited_once_with(db, 'USD', 'SGD', date(2026, 1, 1), lazy_load=True)
    else:
        with pytest.raises(ValueError): await try_auto_post_statement_opening_balance(db, statement, test_user.id, dependencies=None if case == 'missing_provider' else dependencies)
        assert await db.scalar(select(func.count()).select_from(JournalEntry).where(JournalEntry.user_id == test_user.id)) == 0
async def test_statement_opening_contiguous_reverse_upload_supersedes_later_opening(db, test_user): account = Account(user_id=test_user.id, name='SGD Checking', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.flush(); feb_entry = await initialize_opening_positions(db, test_user.id, entry_date=date(2026, 2, 1), balances={account.id: Decimal('500')}, currency='SGD', base_currency='SGD'); assert feb_entry is not None; assert feb_entry.status == JournalEntryStatus.POSTED; statement = StatementSummaryFactory.build(user_id=test_user.id, account_id=account.id, currency='SGD', opening_balance=Decimal('200'), closing_balance=Decimal('500'), period_start=date(2026, 1, 1), period_end=date(2026, 1, 31)); posted = await try_auto_post_statement_opening_balance(db, statement, test_user.id); assert posted is True; await db.refresh(feb_entry); assert feb_entry.status == JournalEntryStatus.VOID; assert feb_entry.void_reason == 'Superseded by earlier statement opening balance'; positions = await list_opening_positions(db, user_id=test_user.id, as_of=date.max); assert len(positions) == 1; assert positions[0].account_id == account.id; assert positions[0].effective_date == date(2026, 1, 1); assert positions[0].amount == Decimal('200'); current_balance = await calculate_account_balance(db, account.id, test_user.id); assert current_balance == Decimal('200'); bs = await generate_balance_sheet(db, test_user.id, as_of_date=date(2026, 2, 28), currency='SGD'); asset_line = next((line for line in bs['assets'] if line['account_id'] == account.id)); assert asset_line['amount'] == Decimal('200')
