async def test_statement_opening_chronological_order_preserves_earlier_opening(db, test_user): account = Account(user_id=test_user.id, name='SGD Checking', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.flush(); await initialize_opening_positions(db, test_user.id, entry_date=date(2025, 1, 1), balances={account.id: Decimal('1000')}, currency='SGD', base_currency='SGD'); statement = StatementSummaryFactory.build(user_id=test_user.id, account_id=account.id, currency='SGD', opening_balance=Decimal('1500'), period_start=date(2025, 2, 1)); posted = await try_auto_post_statement_opening_balance(db, statement, test_user.id); assert posted is False; positions = await list_opening_positions(db, user_id=test_user.id, as_of=date.max); assert len(positions) == 1; assert positions[0].effective_date == date(2025, 1, 1); assert positions[0].amount == Decimal('1000')
