async def test_void_journal_entry_annihilates_balance_cleanly(db, test_user): account = Account(user_id=test_user.id, name='SGD Checking', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.flush(); entry = await initialize_opening_positions(db, test_user.id, entry_date=date(2026, 1, 1), balances={account.id: Decimal('500')}, currency='SGD', base_currency='SGD'); assert await calculate_account_balance(db, account.id, test_user.id) == Decimal('500'); await void_journal_entry(db, entry.id, 'Test void', test_user.id); assert await calculate_account_balance(db, account.id, test_user.id) == Decimal('0'); bs = await generate_balance_sheet(db, test_user.id, as_of_date=date(2026, 1, 31), currency='SGD'); asset_line = next((line for line in bs['assets'] if line['account_id'] == account.id), None); assert asset_line is None or asset_line['amount'] == Decimal('0')
async def test_AC_ledger_2832_1_unexplained_gap_equity_account_and_superseding_opening_position(db, test_user): 'AC-ledger.2832.1'; from src.ledger.extension.account_service import UNEXPLAINED_GAP_EQUITY_CODE, get_or_create_unexplained_gap_equity_account; gap_sgd_1 = await get_or_create_unexplained_gap_equity_account(db, test_user.id, 'SGD'); gap_sgd_2 = await get_or_create_unexplained_gap_equity_account(db, test_user.id, 'sgd'); gap_usd = await get_or_create_unexplained_gap_equity_account(db, test_user.id, 'USD'); assert gap_sgd_1.id == gap_sgd_2.id; assert gap_sgd_1.code == UNEXPLAINED_GAP_EQUITY_CODE == '3198'; assert gap_sgd_1.type == AccountType.EQUITY; assert gap_sgd_1.is_system is True; assert gap_sgd_1.currency == 'SGD'; assert gap_usd.id != gap_sgd_1.id; assert gap_usd.currency == 'USD'; account = Account(user_id=test_user.id, name='SGD Checking', type=AccountType.ASSET, currency='SGD'); db.add(account); await db.flush(); jan_entry = await initialize_opening_positions(db, test_user.id, entry_date=date(2025, 1, 1), balances={account.id: Decimal('1000.00')}, currency='SGD', base_currency='SGD'); assert jan_entry is not None; assert jan_entry.status == JournalEntryStatus.POSTED; jun_entry = await initialize_opening_positions(db, test_user.id, entry_date=date(2025, 6, 1), balances={account.id: Decimal('1500.00')}, currency='SGD', base_currency='SGD', allow_supersede=True); assert jun_entry is not None; assert jun_entry.status == JournalEntryStatus.POSTED; await db.refresh(jan_entry); assert jan_entry.status == JournalEntryStatus.VOID; positions = await list_opening_positions(db, user_id=test_user.id, as_of=date.max); assert len(positions) == 1; assert positions[0].effective_date == date(2025, 6, 1); assert positions[0].amount == Decimal('1500.00'); assert await calculate_account_balance(db, account.id, test_user.id) == Decimal('1500.00')
