count_statement_chain(db, user_id=test_user.id, account_id=sgd_acc.id) is True; assert await release_statement_ledger_effects(db, s_sgd_mar, test_user.id, was_approved=True, reason='Statement retired', dependencies=None) == 0
async def test_audit_completeness_reconcile_chain_lifecycle_and_manual_override_guards(db, test_user): 'AC-extraction.2832.2'; from src.extraction.base.source_vocabulary import BankStatementStatus; from src.extraction.extension.statement_posting import reconcile_account_statement_chain; from src.extraction.extension.statement_workflow import reject_statement_workflow; from src.ledger import calculate_account_balance, list_opening_positions; from src.ledger.extension.account_service import get_or_create_unexplained_gap_equity_account; from src.routers import statements as statements_router; from src.schemas.review import SetOpeningBalanceRequest; acc = Account(user_id=test_user.id, name='OCBC 360', type=AccountType.ASSET, currency='SGD'); db.add(acc); await db.flush(); stmt_manual = StatementSummaryFactory.build(user_id=test_user.id, account_id=acc.id, institution='OCBC', account_last4='1111', currency='SGD', opening_balance=Decimal('2000.00'), manual_opening_balance=Decimal('2500.00'), closing_balance=Decimal('2500.00'), period_start=date(2025, 1, 1), period_end=date(2025, 1, 31), status=BankStatementStatus.APPROVED); db.add(stmt_manual); await db.flush(); assert await reconcile_account_statement_chain(db, user_id=test_user.id, account_id=acc.id) is True; assert await calculate_account_balance(db, acc.id, test_user.id) == Decimal('2500.00'); await statements_router.set_statement_opening_balance(statement_id=stmt_manual.id, request=SetOpeningBalanceRequest(opening_balance=Decimal('3200.00')), db=db, user_id=test_user.id); assert await calculate_account_balance(db, acc.id, test_user.id) == Decimal('3200.00'); await reject_statement_workflow(db, stmt_manual.id, test_user.id, reason='Dormant statement rejected'); assert await calculate_account_balance(db, acc.id, test_user.id) == Decimal('0.00'); assert len(await list_opening_positions(db, user_id=test_user.id, as_of=date.max)) == 0; stmt_mar = StatementSummaryFactory.build(user_id=test_user.id, account_id=acc.id, institution='OCBC', account_last4='1111', currency='SGD', opening_balance=Decimal('4000.00'), closing_balance=Decimal('4000.00'), period_start=date(2025, 3, 1), period_end=date(2025, 3, 31), status=BankStatementStatus.APPROVED); stmt_jun = StatementSummaryFactory.build(user_id=test_user.id, account_id=acc.id, institution='OCBC', account_last4='1111', currency='SGD', opening_balance=Decimal('5000.00'), closing_balance=Decimal('5000.00'), period_start=date(2025, 6, 1), period_end=date(2025, 6, 30), status=BankStatementStatus.APPROVED); db.add_all([stmt_mar, stmt_jun]); await db.flush(); assert await reconcile_account_statement_chain(db, user_id=test_user.id, account_id=acc.id) is True; gap_eq = await get_or_create_unexplained_gap_equity_account(db, test_user.id, 'SGD'); assert await calculate_account_balance(db, gap_eq.id, test_user.id) == Decimal('1000.00'); stmt_mar.status = BankStatementStatus.RETIRED; await db.flush(); assert await reconcile_account_statement_chain(db, user_id=test_user.id, account_id=acc.id) is True; assert await calculate_account_balance(db, gap_eq.id, test_user.id) == Decimal('0.00'); assert await calculate_account_balance(db, acc.id, test_user.id) == Decimal('5000.00')
async def test_foreign_currency_opening_equity_retire_and_gap_zero_hidden(db, test_user): 'AC-extraction.2832.1 AC-extraction.2832.2'; from src.audit import JournalEntrySourceType; from src.extraction.base.source_vocabulary import BankStatementStatus, DocumentStatus, DocumentType; from src.extraction.base.types import RetireStatementCommand; from src.extraction.extension.source_lifecycle import retire_statement; from src.extraction.extension.statement_posting import reconcile_account_statement_chain; from src.extraction.orm.layer1 import UploadedDocument; from src.extraction.orm.layer2 import AtomicTransaction; from src.ledger import Direction, submit_system_journal_entry; from src.ledger.extension.account_service import get_or_create_opening_balance_equity_account, get_or_create_unexplained_gap_equity_account; from src.pricing import FxRate; db.add_all([FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.188304'), rate_date=date(2024, 1, 1), source='test'), FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.190000'), rate_date=date(2024, 2, 1), source='test'), FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.192490'), rate_date=date(2024, 2, 28), source='test'), FxRate(base_currency='SGD', quote_currency='CNY', rate=Decimal('5.195075'), rate_date=date(2024, 2, 28), source='test'), FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.195000'), rate_date=date(2024, 3, 1), source='test'), FxRate(base_currency='CNY', quote_currency='SGD', rate=Decimal('0.195000'), rate_date=date(2024, 3, 31), source='test')]); cny_bank = Account(user_id=test_user.id, name='CMB Savings', type=AccountType.ASSET, currency='CNY'); cny_exp = Account(user_id=test_user.id, name='CNY Dining', type=AccountType.EXPENSE, currency='CNY'); db.add_all([cny_bank, cny_exp]); await db.flush(); doc_jan = UploadedDocument(user_id=test_user.id, file_path='statements/cmb_jan.pdf', file_hash='cmb_jan_hash_2851', original_filename='cmb_jan.pdf', document_type=DocumentType.BANK_STATEMENT, status=DocumentStatus.COMPLETED); doc_mar = UploadedDocument(user_id=test_user.id, file_path='statements/cmb_mar.pdf', file_hash='cmb_mar_hash_2851', original_filename='cmb_mar.pdf', document_type=DocumentType.BANK_STATEMENT, status=DocumentStatus.COMPLETED); db.add_all([doc_jan, doc_mar]); await db.flush(); stmt_jan = StatementSummaryFactory.build(user_id=test_user.id, uploaded_document_id=doc_jan.id, account_id=cny_bank.id, institution='CMB', account_last4='8888', currency='CNY', opening_balance=Decimal('38500.00'), closing_balance=Decimal('38000.00'), period_start=date(2024, 1, 1), period_end=date(2024, 2, 28), status=BankStatementStatus.APPROVED); stmt_mar = StatementSummaryFactory.build(user_id=test_user.id, uploaded_document_id=doc_mar.id, account_id=cny_bank.id, institution='CMB', account_last4='8888', currency='CNY', opening_balance=Decimal('40000.00'), closing_balance=Decimal('40000.00'), period_start=date(2024, 3, 1), period_end=date(2024, 3, 31), status=BankStatementStatus.APPROVED); db.add_all([stmt_jan, stmt_mar]); await db.flush(); txn_jan = AtomicTransaction(user_id=test_user.id, txn_date=date(2024, 2, 1), amount=Decimal('500.00'), direction='OUT', description='Hotpot Dinner', currency='CNY', dedup_hash='cmb_jan_txn_2851', source_documents=[{'doc_id': str(doc_jan.id), 'doc_type': 'bank_statement'}]); db.add(txn_jan); await db.flush(); await submit_system_journal_entry(db, user_id=test_user.id, entry_date=date(2024, 2, 1), memo='Hotpot Dinner', lines_data=[{'account_id': cny_exp.id, 'direction': Direction.DEBIT, 'amount': Decimal('500.00'), 'currency': 'CNY', 'fx_rate': Decimal('0.190000')}, {'account_id': cny_bank.id, 'direction': Direction.CREDIT, 'amount': Decimal('500.00'), 'currency': 'CNY', 'fx_rate': Decimal('0.190000')}], base_currency='SGD', source_type=JournalEntrySourceType.AUTO_PARSED, source_id=txn_jan.id, operation='statement-posting'); assert await reconcile_account_statement_chain(db, user_id=test_user.id, account_id=cny_bank.id) is True; obe_cny = await get_or_create_opening_balance_equity_account(db, test_user.id, 'CNY', match_currency=True); assert obe_cny.currency == 'CNY'; assert await calculate_account_balance(db, obe_cny.id, test_user.id) == Decimal('38500.00'); bs_cny = await generate_balance_sheet(db, test_user.id, as_of_date=date(2024, 2, 28), currency='CNY'); assert bs_cny['is_balanced'] is True; assert bs_cny['total_assets'] == Decimal('38000.00'); assert bs_cny['total_equity'] == Decimal('38500.00'); assert bs_cny['net_income'] == Decimal('-500.00'); assert bs_cny['unrealized_fx_gain_loss'] == Decimal('0.00'); assert bs_cny['cta_adjustment'] == Decimal('0.00'); assert [line['name'] for line in bs_cny['equity']] == ['Opening Balance Equity']; retired = await retire_statement(db, RetireStatementCommand(statement_id=stmt_jan.id, user_id=test_user.id)); assert retired.status == BankStatementStatus.RETIRED; gap_eq_cny = await get_or_create_unexplained_gap_equity_account(db, test_user.id, 'CNY'); assert await calculate_account_balance(db, gap_eq_cny.id, test_user.id) == Decimal('0.00'); assert await calculate_account_balance(db, cny_bank.id, test_user.id) == Decimal('40000.00'); bs_mar_cny = await generate_balance_sheet(db, test_user.id, as_of_date=date(2024, 3, 31), currency='CNY'); assert bs_mar_cny['is_balanced'] is True; assert bs_mar_cny['total_assets'] == Decimal('40000.00'); assert bs_mar_cny['total_equity'] == Decimal('40000.00'); assert [line['name'] for line in bs_mar_cny['equity']] == ['Opening Balance Equity']
